package identity

// Parity with the TypeScript prototype over the interview corpora.
//
// Fixture provenance: testdata/expected-decisions.json was generated by
// running the prototype itself from the repository root. The exact
// re-runnable recipe is the fixture's generatedBy field, reproduced here
// verbatim: paste it to set GEN to the recorded command via a heredoc and
// then run it, so the second stage stamps the identical command back into
// generatedBy and the output is byte-identical:
//
// GEN=$(cat <<'GENEOF'
// bun --cwd=tools/episode-triage-poc -e 'import("./analyze.ts").then(async ({analyze}) => { const splits: Record<string, unknown> = {}; for (const s of ["dev", "supplemental"]) { const c: any = await Bun.file("artifacts/interview-eval-" + s + ".json").json(); splits[s] = c.cases.map((c: any) => { const n: any = analyze(c.snapshot, c.id).nextSelection; return {id: c.id, episode: n ? n.episode : null, basename: n ? n.basename : null}; }); } console.log(JSON.stringify({splits})); });' | bun -e 'const t = await Bun.stdin.text(); const s = JSON.parse(t); console.log(JSON.stringify({generatedBy: process.env.GEN, splits: s.splits}, null, 2));' > internal/anime/identity/testdata/expected-decisions.json
// GENEOF
// )
// bun --cwd=tools/episode-triage-poc -e 'import("./analyze.ts").then(async ({analyze}) => { const splits: Record<string, unknown> = {}; for (const s of ["dev", "supplemental"]) { const c: any = await Bun.file("artifacts/interview-eval-" + s + ".json").json(); splits[s] = c.cases.map((c: any) => { const n: any = analyze(c.snapshot, c.id).nextSelection; return {id: c.id, episode: n ? n.episode : null, basename: n ? n.basename : null}; }); } console.log(JSON.stringify({splits})); });' | bun -e 'const t = await Bun.stdin.text(); const s = JSON.parse(t); console.log(JSON.stringify({generatedBy: process.env.GEN, splits: s.splits}, null, 2));' > internal/anime/identity/testdata/expected-decisions.json
//
// The first stage imports analyze from analyze.ts and maps each case's
// nextSelection to {id, episode, basename} for the dev and supplemental
// splits of artifacts/interview-eval-{dev,supplemental}.json; the second
// stage attaches generatedBy from GEN. Copies of the corpora live in
// testdata/interview-eval-dev.json and
// testdata/interview-eval-supplemental.json. The holdout set was never
// opened. Parity is asserted on the decision only — selected episode and
// basename, or no selection — never on an evidence report.

import (
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// corpusSnapshot mirrors only the fields the decision reads.
type corpusSnapshot struct {
	Entries []corpusEntry `json:"entries"`
	Context corpusContext `json:"context"`
}

// corpusEntry mirrors one prototype ObservedEntry.
type corpusEntry struct {
	Basename            string   `json:"basename"`
	BirthNs             *string  `json:"birthNs"`
	MtimeNs             *string  `json:"mtimeNs"`
	EpisodeTags         []string `json:"episodeTags"`
	Errors              []string `json:"errors"`
	ChangedBetweenStats *bool    `json:"changedBetweenStats"`
}

// corpusContext keeps raw tokens so fractional and string values stay visible.
type corpusContext struct {
	Progress     any `json:"progress"`
	ExpectedNext any `json:"expectedNext"`
}

// corpusFile is one interview case: requested decision plus snapshot.
type corpusFile struct {
	Cases []corpusCase `json:"cases"`
}

// corpusCase is a single interview case.
type corpusCase struct {
	ID       string         `json:"id"`
	Snapshot corpusSnapshot `json:"snapshot"`
}

// expectedFixture is the prototype-derived decision set.
type expectedFixture struct {
	GeneratedBy string                        `json:"generatedBy"`
	Splits      map[string][]expectedDecision `json:"splits"`
}

// expectedDecision is the decision only: episode and basename, or neither.
type expectedDecision struct {
	ID       string  `json:"id"`
	Episode  *int    `json:"episode"`
	Basename *string `json:"basename"`
}

// corpusNumber maps a raw JSON token to a float64 reading. Numbers stay
// numbers; anything else marks the token set but unusable.
func corpusNumber(v any) (float64, bool) {
	if v == nil {
		return 0, false
	}
	if f, ok := v.(float64); ok {
		return f, true
	}
	return math.NaN(), true
}

// corpusRequest maps one interview snapshot to the port request.
func corpusRequest(c corpusCase) Request {
	entries := make([]Entry, 0, len(c.Snapshot.Entries))
	for _, e := range c.Snapshot.Entries {
		var birth, mtime string
		if e.BirthNs != nil {
			birth = *e.BirthNs
		}
		if e.MtimeNs != nil {
			mtime = *e.MtimeNs
		}
		var changed bool
		if e.ChangedBetweenStats != nil {
			changed = *e.ChangedBetweenStats
		}
		entries = append(entries, Entry{
			Basename: e.Basename,
			BirthNs:  birth,
			MtimeNs:  mtime,
			Tags:     append([]string(nil), e.EpisodeTags...),
			Err:      strings.Join(e.Errors, "; "),
			Changed:  changed,
		})
	}
	progress, progressSet := corpusNumber(c.Snapshot.Context.Progress)
	next, nextSet := corpusNumber(c.Snapshot.Context.ExpectedNext)
	return Request{Entries: entries, Context: Context{
		ProgressSet:     progressSet,
		Progress:        progress,
		ExpectedNextSet: nextSet,
		ExpectedNext:    next,
	}}
}

// assertParityCase asserts one prototype-derived decision and reports
// whether it matched, so the test function reads as a loop over cases.
func assertParityCase(t *testing.T, id Identifier, byID map[string]corpusCase, want expectedDecision) bool {
	t.Helper()
	c, ok := byID[want.ID]
	if !ok {
		t.Errorf("MISMATCH %s: case missing from corpus", want.ID)
		return false
	}
	got := id.Identify(corpusRequest(c))
	var gotEp *int
	var gotBase *string
	if got.Next != nil {
		ep, base := got.Next.Episode, got.Next.Basename
		gotEp, gotBase = &ep, &base
	}
	if !intPtrEqual(gotEp, want.Episode) || !strPtrEqual(gotBase, want.Basename) {
		t.Errorf("MISMATCH %s: got episode=%v basename=%v want episode=%v basename=%v",
			want.ID, ptrStr(gotEp), ptrStr(gotBase), ptrStr(want.Episode), ptrStr(want.Basename))
		return false
	}
	return true
}

// TestParity asserts the port decision matches the prototype on every
// interview case, printing per-split match counts and each mismatch by id.
func TestParity(t *testing.T) {
	t.Parallel()
	raw, err := os.ReadFile(filepath.Join("testdata", "expected-decisions.json"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var fixture expectedFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("decode fixture: %v", err)
	}
	if fixture.GeneratedBy == "" {
		t.Fatal("fixture must record how it was produced")
	}
	files := map[string]string{"dev": "interview-eval-dev.json", "supplemental": "interview-eval-supplemental.json"}
	id := New()
	for split, file := range files {
		raw, err := os.ReadFile(filepath.Join("testdata", file))
		if err != nil {
			t.Fatalf("read corpus %s: %v", split, err)
		}
		var corpus corpusFile
		if err := json.Unmarshal(raw, &corpus); err != nil {
			t.Fatalf("decode corpus %s: %v", split, err)
		}
		byID := make(map[string]corpusCase, len(corpus.Cases))
		for _, c := range corpus.Cases {
			byID[c.ID] = c
		}
		matched := 0
		for _, want := range fixture.Splits[split] {
			if assertParityCase(t, id, byID, want) {
				matched++
			}
		}
		t.Logf("parity %s: %d/%d matched", split, matched, len(fixture.Splits[split]))
	}
}

// intPtrEqual reports whether two optional ordinals agree.
func intPtrEqual(a, b *int) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return *a == *b
}

// strPtrEqual reports whether two optional basenames agree.
func strPtrEqual(a, b *string) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return *a == *b
}

// ptrStr renders an optional value for mismatch output.
func ptrStr[T any](p *T) any {
	if p == nil {
		return nil
	}
	return *p
}
